@use "../variables" as *;
@use "sass:color";

@import url("https://fonts.googleapis.com/css?family=Cabin:400,400italic,700,700italic,100,100italic&display=swap");
@import url("https://fonts.googleapis.com/css?family=Inknut+Antiqua:400,400italic,700,700italic,100,100italic&display=swap");

// Fallback font metrics tuned to match web fonts and reduce layout shift.
@font-face {
  font-family: "Cabin Fallback";
  src: local("Arial");
  ascent-override: 96.5%;
  descent-override: 25%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Inknut Antiqua Fallback";
  src: local("Times New Roman");
  ascent-override: 170.3%;
  descent-override: 87.6%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "FontAwesome";
  font-style: normal;
  font-weight: normal;
  font-display: swap;
  src: url("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/fonts/fontawesome-webfont.woff2?v=4.7.0") format("woff2"),
  url("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/fonts/fontawesome-webfont.woff?v=4.7.0") format("woff"),
  url("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/fonts/fontawesome-webfont.ttf?v=4.7.0") format("truetype");
}

$cabin: 'Cabin', 'Cabin Fallback', Arial, Helvetica, sans-serif;

$inknut: 'Inknut Antiqua', 'Inknut Antiqua Fallback', serif;

body,
html {
  font-family: $cabin;
  font-weight: 400;
  font-size: 10px;
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
fieldset {
  font-family: $cabin;
  font-weight: 400;
}

a {
  text-decoration: none !important;
  outline: none !important;
  cursor: pointer !important;
  color: inherit;
  &:link {
    font-weight: 500;
    color: inherit;
  }
  &:visited {
    color: inherit;
  }
  &:hover {
    font-weight: bold;
    color: inherit;
  }
  &:active {
    color: inherit;
  }
}

p {
  font-size: 1.1rem;
  color: inherit;
  line-height: 1.4rem;
  margin-bottom: 0 !important;
}

h3 {
  display: inline-block;
  margin-top: 0;
  font-size: 2.2rem;
}

h4 {
  line-height: 1.1rem;
  font-size: 1.8rem;
  color: inherit;
}

hr {
  border: 1px solid var(--secondary-bg);
}

ul {
  list-style-type: none !important;
  padding: 0;
}
